import React, { useState } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { useQuery, useMutation, useQueryClient } from 'react-query';
import { getPrompt, likePrompt, usePrompt, deletePrompt } from '../api/prompts';
import { useAuth } from '../contexts/AuthContext';
import { FiHeart, FiCopy, FiEye, FiTrendingUp, FiUser, FiClock, FiEdit, FiTrash2, FiArrowLeft } from 'react-icons/fi';
import toast from 'react-hot-toast';

const PromptDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { user, isAuthenticated } = useAuth();
  const queryClient = useQueryClient();
  const [isLiked, setIsLiked] = useState(false);

  const { data: prompt, isLoading, error } = useQuery(
    ['prompt', id],
    () => getPrompt(id),
    {
      onSuccess: (data) => {
        setIsLiked(data.likes?.some(like => like._id === user?._id));
      },
    }
  );

  const likeMutation = useMutation(likePrompt, {
    onSuccess: (data) => {
      setIsLiked(data.isLiked);
      queryClient.invalidateQueries(['prompt', id]);
      toast.success(isLiked ? 'Removed from likes' : 'Added to likes');
    },
    onError: () => {
      toast.error('Failed to update like');
    },
  });

  const usePromptMutation = useMutation(usePrompt, {
    onSuccess: () => {
      queryClient.invalidateQueries(['prompt', id]);
      toast.success('Usage count updated');
    },
    onError: () => {
      toast.error('Failed to update usage count');
    },
  });

  const deleteMutation = useMutation(deletePrompt, {
    onSuccess: () => {
      queryClient.invalidateQueries(['prompts']);
      toast.success('Prompt deleted successfully');
      navigate('/');
    },
    onError: () => {
      toast.error('Failed to delete prompt');
    },
  });

  const handleLike = () => {
    if (!isAuthenticated) {
      toast.error('Please login to like prompts');
      return;
    }
    likeMutation.mutate(id);
  };

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(prompt.content);
      toast.success('Prompt copied to clipboard!');
    } catch (err) {
      toast.error('Failed to copy prompt');
    }
  };

  const handleUse = () => {
    usePromptMutation.mutate(id);
  };

  const handleEdit = () => {
    navigate(`/prompts/${id}/edit`);
  };

  const handleDelete = () => {
    if (window.confirm('Are you sure you want to delete this prompt?')) {
      deleteMutation.mutate(id);
    }
  };

  const formatDate = (dateString) => {
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const getCategoryColor = (category) => {
    const colors = {
      chatgpt: 'bg-green-100 text-green-800',
      midjourney: 'bg-purple-100 text-purple-800',
      dalle: 'bg-blue-100 text-blue-800',
      bard: 'bg-yellow-100 text-yellow-800',
      claude: 'bg-orange-100 text-orange-800',
      other: 'bg-gray-100 text-gray-800',
    };
    return colors[category] || colors.other;
  };

  if (isLoading) {
    return (
      <div className="max-w-4xl mx-auto">
        <div className="animate-pulse">
          <div className="h-8 bg-gray-200 rounded mb-4"></div>
          <div className="h-64 bg-gray-200 rounded mb-4"></div>
          <div className="h-4 bg-gray-200 rounded mb-2"></div>
          <div className="h-4 bg-gray-200 rounded w-3/4"></div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="max-w-4xl mx-auto text-center py-12">
        <div className="text-red-600 text-lg mb-4">Error loading prompt</div>
        <button onClick={() => navigate('/')} className="btn-primary">
          Go Back
        </button>
      </div>
    );
  }

  if (!prompt) {
    return (
      <div className="max-w-4xl mx-auto text-center py-12">
        <div className="text-gray-600 text-lg mb-4">Prompt not found</div>
        <button onClick={() => navigate('/')} className="btn-primary">
          Go Back
        </button>
      </div>
    );
  }

  const isAuthor = user?._id === prompt.author._id;

  return (
    <div className="max-w-4xl mx-auto">
      {/* Header */}
      <div className="mb-6">
        <button
          onClick={() => navigate(-1)}
          className="flex items-center space-x-2 text-gray-600 hover:text-gray-900 mb-4"
        >
          <FiArrowLeft className="w-4 h-4" />
          <span>Back</span>
        </button>

        <div className="flex items-start justify-between">
          <div className="flex-1">
            <h1 className="text-3xl font-bold text-gray-900 mb-2">{prompt.title}</h1>
            <div className="flex items-center space-x-4 text-sm text-gray-600">
              <Link
                to={`/user/${prompt.author.username}`}
                className="flex items-center space-x-1 hover:text-blue-600 transition-colors"
              >
                <FiUser className="w-4 h-4" />
                <span>{prompt.author.username}</span>
              </Link>
              <span className="flex items-center space-x-1">
                <FiClock className="w-4 h-4" />
                <span>{formatDate(prompt.createdAt)}</span>
              </span>
              <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${getCategoryColor(prompt.category)}`}>
                {prompt.category}
              </span>
            </div>
          </div>

          {isAuthor && (
            <div className="flex space-x-2">
              <button
                onClick={handleEdit}
                className="flex items-center space-x-1 px-3 py-1.5 text-sm text-gray-600 hover:text-blue-600 hover:bg-blue-50 rounded-md transition-colors"
              >
                <FiEdit className="w-4 h-4" />
                <span>Edit</span>
              </button>
              <button
                onClick={handleDelete}
                className="flex items-center space-x-1 px-3 py-1.5 text-sm text-red-600 hover:text-red-700 hover:bg-red-50 rounded-md transition-colors"
              >
                <FiTrash2 className="w-4 h-4" />
                <span>Delete</span>
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Content */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2">
          {/* Description */}
          {prompt.description && (
            <div className="card mb-6">
              <h2 className="text-lg font-semibold text-gray-900 mb-2">Description</h2>
              <p className="text-gray-700">{prompt.description}</p>
            </div>
          )}

          {/* Prompt Content */}
          <div className="card mb-6">
            <h2 className="text-lg font-semibold text-gray-900 mb-4">Prompt</h2>
            <div className="bg-gray-50 rounded-lg p-4 border">
              <pre className="whitespace-pre-wrap text-gray-800 font-mono text-sm">{prompt.content}</pre>
            </div>
            <div className="mt-4 flex space-x-2">
              <button
                onClick={handleCopy}
                className="flex items-center space-x-1 px-3 py-1.5 text-sm text-gray-600 hover:text-blue-600 hover:bg-blue-50 rounded-md transition-colors"
              >
                <FiCopy className="w-4 h-4" />
                <span>Copy</span>
              </button>
              <button
                onClick={handleUse}
                className="flex items-center space-x-1 px-3 py-1.5 text-sm text-gray-600 hover:text-green-600 hover:bg-green-50 rounded-md transition-colors"
              >
                <FiTrendingUp className="w-4 h-4" />
                <span>Use</span>
              </button>
            </div>
          </div>

          {/* Tags */}
          {prompt.tags && prompt.tags.length > 0 && (
            <div className="card">
              <h2 className="text-lg font-semibold text-gray-900 mb-4">Tags</h2>
              <div className="flex flex-wrap gap-2">
                {prompt.tags.map((tag, index) => (
                  <span key={index} className="tag">
                    #{tag}
                  </span>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Sidebar */}
        <div className="space-y-6">
          {/* Stats */}
          <div className="card">
            <h3 className="text-lg font-semibold text-gray-900 mb-4">Statistics</h3>
            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <span className="flex items-center space-x-2 text-gray-600">
                  <FiEye className="w-4 h-4" />
                  <span>Views</span>
                </span>
                <span className="font-medium">{prompt.views}</span>
              </div>
              <div className="flex items-center justify-between">
                <span className="flex items-center space-x-2 text-gray-600">
                  <FiTrendingUp className="w-4 h-4" />
                  <span>Uses</span>
                </span>
                <span className="font-medium">{prompt.usageCount}</span>
              </div>
              <div className="flex items-center justify-between">
                <span className="flex items-center space-x-2 text-gray-600">
                  <FiHeart className="w-4 h-4" />
                  <span>Likes</span>
                </span>
                <span className="font-medium">{prompt.likes?.length || 0}</span>
              </div>
            </div>
          </div>

          {/* Actions */}
          <div className="card">
            <h3 className="text-lg font-semibold text-gray-900 mb-4">Actions</h3>
            <div className="space-y-3">
              <button
                onClick={handleLike}
                disabled={likeMutation.isLoading}
                className={`w-full flex items-center justify-center space-x-2 px-4 py-2 rounded-lg transition-colors ${
                  isLiked
                    ? 'bg-red-100 text-red-700 hover:bg-red-200'
                    : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                }`}
              >
                <FiHeart className={`w-4 h-4 ${isLiked ? 'fill-current' : ''}`} />
                <span>{isLiked ? 'Liked' : 'Like'}</span>
              </button>
              <button
                onClick={handleCopy}
                className="w-full flex items-center justify-center space-x-2 px-4 py-2 bg-blue-100 text-blue-700 hover:bg-blue-200 rounded-lg transition-colors"
              >
                <FiCopy className="w-4 h-4" />
                <span>Copy Prompt</span>
              </button>
            </div>
          </div>

          {/* Author Info */}
          <div className="card">
            <h3 className="text-lg font-semibold text-gray-900 mb-4">Author</h3>
            <div className="flex items-center space-x-3">
              <div className="w-10 h-10 bg-blue-600 rounded-full flex items-center justify-center">
                <span className="text-white font-medium">
                  {prompt.author.username.charAt(0).toUpperCase()}
                </span>
              </div>
              <div>
                <Link
                  to={`/user/${prompt.author.username}`}
                  className="font-medium text-gray-900 hover:text-blue-600 transition-colors"
                >
                  {prompt.author.username}
                </Link>
                {prompt.author.bio && (
                  <p className="text-sm text-gray-600 mt-1">{prompt.author.bio}</p>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PromptDetail;
